CREATE TABLE app_user (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, role VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, email_verified BOOLEAN NOT NULL DEFAULT FALSE, license_plate VARCHAR(15), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0, CHECK (role IN ('CUSTOMER', 'MERCHANT', 'ASSOCIATION', 'TOWN_HALL')), CHECK (status IN ('PENDING', 'ACTIVE', 'DISABLED')));
CREATE TABLE user_permission (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, granted_by UUID NOT NULL REFERENCES app_user(id), permission VARCHAR(50) NOT NULL, UNIQUE (user_id, permission), CHECK (granted_by <> user_id), CHECK (permission IN ('MANAGE_AGENTS', 'VALIDATE_MERCHANTS', 'CONFIGURE_PROGRAM', 'CONFIGURE_BENEFITS', 'VIEW_INDICATORS', 'EXPORT_INDICATORS', 'PUBLISH_ANNOUNCEMENTS')));
CREATE TABLE merchant_request (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, store_name VARCHAR(150) NOT NULL, store_address VARCHAR(255) NOT NULL, status VARCHAR(50) NOT NULL, refusal_reason VARCHAR(255), reviewed_by UUID REFERENCES app_user(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, CHECK (status IN ('PENDING', 'ACCEPTED', 'REFUSED')));
CREATE INDEX idx_merchant_request_user_id ON merchant_request(user_id);
CREATE INDEX idx_merchant_request_status ON merchant_request(status);
